import ctypes, os, resource, signal
libc = ctypes.CDLL(None, use_errno=True)
def prctl(option, arg2=0, arg3=0):
    call = libc.prctl
    call.argtypes = [ctypes.c_int, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_ulong]
    call.restype = ctypes.c_int
    r = call(option, arg2, arg3, 0, 0)
    print('prctl', option, r, os.strerror(ctypes.get_errno()) if r!=0 else '')
prctl(36,1)
prctl(38,1)
for kind, name in ((resource.RLIMIT_AS,'AS'),(resource.RLIMIT_CPU,'CPU'),(resource.RLIMIT_NOFILE,'NOFILE'),(resource.RLIMIT_NPROC,'NPROC'),(resource.RLIMIT_FSIZE,'FSIZE'),(resource.RLIMIT_CORE,'CORE')):
    print(name, resource.getrlimit(kind))
